  "\u2014 step-by-step user guide for beginners": "\u2014 \ucd08\ubcf4\uc790\ub97c \uc704\ud55c \ub2e8\uacc4\ubcc4 \uc0ac\uc6a9\uc790 \uac00\uc774\ub4dc",
